import { Context } from './context.js';
import { Application } from './application.js';
export async function run(label) {
    /** @type {any} */
    const app = new Application(label);
    const same = await app.init();
    console.log(same === app, same.name());
    const again = await app.init();
    console.log(again === app);
    /** @type {any} */
    const context = new Context();
    console.log((await context.init()).name());
}
